insert into public.lessons (topic_id, title, content, worked_example) select t.id, 'Introduction to Algebra', 'Algebra uses letters to represent unknown numbers. An expression like 3x + 2 means 3 times x plus 2. To evaluate an expression, substitute the value of x and simplify using the order of operations (BODMAS).', 'Evaluate 3x + 2 when x = 5: 3(5) + 2 = 15 + 2 = 17.' from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='mathematics' and t.name='Algebra';
insert into public.lessons (topic_id, title, content, worked_example) select t.id, 'Cells: The Basic Unit of Life', 'All living organisms are made of cells. Plant cells have a cell wall, chloroplasts and a large vacuole; animal cells do not. Both have a nucleus, cytoplasm and cell membrane.', 'Compare plant and animal cells in a table listing three differences.' from public.topics t join public.subjects s on s.id=t.subject_id where s.slug='biology' and t.name='Cells';
