insert into public.question_options (question_id, option_text, position) select id, 'Yangtze', 3 from public.questions where question_text='Which is the longest river in the world?' and not exists (select 1 from public.question_options where question_id = (select id from public.questions where question_text='Which is the longest river in the world?') and position=3);
insert into public.question_options (question_id, option_text, position) select id, 'Mississippi', 4 from public.questions where question_text='Which is the longest river in the world?' and not exists (select 1 from public.question_options where question_id = (select id from public.questions where question_text='Which is the longest river in the world?') and position=4);
insert into public.question_answers (question_id, correct_option_ids) select q.id, array(select o.id::text from public.question_options o where o.question_id=q.id and o.option_text='Nile') from public.questions q where q.question_text='Which is the longest river in the world?' on conflict (question_id) do nothing;
